    "Importing will replace the current rules in this editor. Continue?": "Việc nhập sẽ thay thế các quy tắc hiện có trong trình chỉnh sửa này. Tiếp tục?",
    "Le Van Toan plugin data scan complete. Order address rows: %1$d total (%4$d billing, %5$d shipping). Safe order sync: %2$d address rows across %6$d orders (%7$d old three-level rows, %8$d new two-level rows). Order address rows needing official mapping/manual review: %3$d.": "Đã hoàn tất quét dữ liệu plugin Lê Văn Toàn. Dòng địa chỉ đơn hàng: tổng cộng %1$d (%4$d thanh toán, %5$d giao hàng). Có thể đồng bộ an toàn: %2$d dòng địa chỉ trong %6$d đơn hàng (%7$d dòng địa chỉ ba cấp cũ, %8$d dòng địa chỉ hai cấp mới). Dòng địa chỉ đơn hàng cần ánh xạ chính thức/xem xét thủ công: %3$d.",
    "Le Van Toan plugin data sync batch complete. Updated %1$d orders and synced %2$d order address rows. Updated %3$d users and synced %4$d customer address rows. Synced %5$d shipment orders. Remaining safe order address rows: %6$d. Remaining safe customer address rows: %7$d. Remaining address rows needing mapping/manual review: %8$d order rows and %9$d customer rows.": "Đã hoàn tất một đợt đồng bộ dữ liệu plugin Lê Văn Toàn. Đã cập nhật %1$d đơn hàng và đồng bộ %2$d dòng địa chỉ đơn hàng. Đã cập nhật %3$d người dùng và đồng bộ %4$d dòng địa chỉ khách hàng. Đã đồng bộ %5$d đơn hàng có vận đơn. Còn %6$d dòng địa chỉ đơn hàng an toàn. Còn %7$d dòng địa chỉ khách hàng an toàn. Số dòng địa chỉ cần ánh xạ/xem xét thủ công còn lại: %8$d dòng đơn hàng và %9$d dòng khách hàng.",
